"""Write the compact construction seed for the G513 LKTS(57) from a pipeline run dir."""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from g513_groups import *
run = sys.argv[1]; out = sys.argv[2]
res = json.load(open(os.path.join(run, "base_resolutions.json")))
names = ["S0", "B1", "B2", "B3", "B4"]
stabs = [P27, F57, F57, F57P, F57P]
extra = [[], [gamma(1, 1)], [gamma(2, 1)], [gamma(1, -1)], [gamma(2, -1)]]
seed = {
    "description": "LKTS(57) seed: points (x,i) in Z19 x Z3 encoded 19*i+x; group G513 generated by G_generators; "
                   "each base is a resolved KTS(57) given by its 28 classes; constituents are g(base) for g in G/H "
                   "(H = base stabilizer, generated by stabilizer_generators). extra_base_symmetry is informational.",
    "point_encoding": "19*i+x",
    "certificate_header": "# LKTS(57) candidate from G513 pipeline (unverified until checked)",
    "G_generators": {"tau": list(tau), "nu": list(nu), "rho": list(rho)},
    "bases": [{"name": n, "stabilizer_generators": [list(g) for g in st], "extra_base_symmetry": [list(g) for g in ex],
               "classes": res[j]} for j, (n, st, ex) in enumerate(zip(names, stabs, extra))],
}
json.dump(seed, open(out, "w"))
print("wrote", out)
